23	    #[inline]
24	    pub fn random(&mut self) -> PointIdType {
25	        self.thread_rng.random_range(1..u64::MAX).into()
26	    }
27	
28	    #[inline]
29	    pub fn unique(&mut self) -> PointIdType {
30	        for _ in 0..100_000 {
31	            let id = self.random();
32	            if let PointIdType::NumId(num) = id
33	                && self.used.insert(num)
34	            {
35	                return id;
36	            }
37	        }
38	        panic!("failed to generate unique point ID after 100000 attempts");
39	    }
40	}
