46	pub fn random_segment(path: &Path, opnum: SeqNumberType, num_vectors: u64, dim: usize) -> Segment {
47	    let mut id_gen = PointIdGenerator::default();
48	    let mut segment = build_simple_segment(path, dim, Distance::Dot).unwrap();
49	    let mut rnd = rand::rng();
50	    let payload_key = "number";
